// v6.5: 업로드된 JLPT N5~N3 단어를 기존 학습 DB에 중복 없이 보강
(function mergeUploadedJlptWords(){
  const src=window.JLPT_WORD_DATA||{},seen=new Set(DB.cards.map(c=>`${normalizeJP(c.jp)}|${normalizeJP(c.reading||'')}`));
  for(const level of ['N5','N4','N3']){
    for(const w of (src[level]||[])){
      const key=`${normalizeJP(w.jp)}|${normalizeJP(w.reading||'')}`;
      if(seen.has(key))continue;seen.add(key);
      DB.cards.push({id:`jlpt-${level.toLowerCase()}-${String(w.id||'').replace(/[^a-zA-Z0-9가-힣_-]/g,'')}`,kind:'word',jp:w.jp,ko:w.ko,reading:w.reading||'',level,category:`JLPT ${level} 보강`,note:'업로드 단어 모음에서 보강',extra:{example:(w.examples||[])[0]||'',translation:''},priority:level==='N3'?4:3});
    }
  }
})();
