function storageOwner(){return String(window.DACO_CLOUD_USER_ID||'guest').replace(/[^a-zA-Z0-9_-]/g,'_')}
function stateKey(){return BASE_KEY+'_'+storageOwner()}
function backupKey(){return stateKey()+'_auto_backup'}
