const PARTICLE_DATA=[{"p":"は","ko":"~은/는 · 화제 제시","use":"이미 알고 있는 화제나 대비를 꺼낼 때","ex":"私は会社員です。","tr":"저는 회사원입니다."},{"p":"が","ko":"~이/가 · 주어/새 정보","use":"누가/무엇이인지 새로 특정하거나 존재를 말할 때","ex":"猫がいます。","tr":"고양이가 있습니다."},{"p":"を","ko":"~을/를 · 목적어","use":"동작이 직접 미치는 대상을 나타낼 때","ex":"水を飲みます。","tr":"물을 마십니다."},{"p":"に","ko":"~에/에게 · 시간·도착·대상","use":"정확한 시간, 도착점, 존재 장소, 받는 사람 등에 사용","ex":"7時に起きます。","tr":"7시에 일어납니다."},{"p":"へ","ko":"~으로/에게 · 방향","use":"이동의 방향을 강조할 때","ex":"日本へ行きます。","tr":"일본으로 갑니다."},{"p":"で","ko":"~에서/으로 · 행동 장소·수단","use":"행동이 일어나는 장소나 수단을 나타낼 때","ex":"図書館で勉強します。","tr":"도서관에서 공부합니다."},{"p":"と","ko":"~와/과 · 함께/인용","use":"함께하는 상대 또는 말·생각의 내용을 인용할 때","ex":"友達と映画を見ます。","tr":"친구와 영화를 봅니다."},{"p":"から","ko":"~부터/~에서 · 시작점","use":"시간·장소의 시작점 또는 원인을 나타낼 때","ex":"9時から働きます。","tr":"9시부터 일합니다."},{"p":"まで","ko":"~까지 · 끝점","use":"시간·장소의 끝 범위를 나타낼 때","ex":"5時まで働きます。","tr":"5시까지 일합니다."},{"p":"の","ko":"~의 · 소유/수식","use":"명사와 명사를 연결해 소속·성질을 나타낼 때","ex":"会社の車です。","tr":"회사 차입니다."},{"p":"も","ko":"~도","use":"앞에서 말한 것과 같은 성격의 대상을 추가할 때","ex":"私も行きます。","tr":"저도 갑니다."},{"p":"や","ko":"~나 ~ 등","use":"여러 항목 중 일부만 예로 들 때","ex":"パンや卵を買いました。","tr":"빵이나 달걀 등을 샀습니다."},{"p":"か","ko":"~인가 / ~나","use":"질문 또는 A인지 B인지 선택을 나타낼 때","ex":"コーヒーかお茶にします。","tr":"커피나 차로 하겠습니다."},{"p":"ね","ko":"~네요/~죠","use":"상대의 공감·확인을 부드럽게 구할 때","ex":"今日は暑いですね。","tr":"오늘 덥네요."},{"p":"よ","ko":"~요 · 정보 강조","use":"상대가 모를 만한 정보를 알려주거나 강조할 때","ex":"この店は安いですよ。","tr":"이 가게는 싸요."},{"p":"だけ","ko":"~만","use":"한정된 범위만 긍정할 때","ex":"水だけ飲みます。","tr":"물만 마십니다."},{"p":"しか","ko":"~밖에 · 반드시 부정과 함께","use":"그것 이외에는 없다는 강한 한정을 나타낼 때","ex":"千円しかありません。","tr":"천 엔밖에 없습니다."},{"p":"くらい","ko":"~정도","use":"수량·시간의 대략적인 정도를 나타낼 때","ex":"10分くらいかかります。","tr":"10분 정도 걸립니다."},{"p":"ごろ","ko":"~쯤 · 시각","use":"정확하지 않은 시각을 말할 때","ex":"3時ごろ来てください。","tr":"3시쯤 와 주세요."},{"p":"より","ko":"~보다","use":"비교의 기준을 나타낼 때","ex":"電車はバスより速いです。","tr":"전철은 버스보다 빠릅니다."},{"p":"ほど","ko":"~정도/~만큼","use":"정도나 비교 기준을 나타낼 때","ex":"思ったほど高くないです。","tr":"생각한 만큼 비싸지 않습니다."},{"p":"について","ko":"~에 대해서","use":"말하거나 생각하는 주제를 구체적으로 나타낼 때","ex":"価格について話します。","tr":"가격에 대해 이야기합니다."},{"p":"によって","ko":"~에 따라/~에 의해","use":"원인·방법·차이를 만드는 기준을 나타낼 때","ex":"人によって考え方が違います。","tr":"사람에 따라 생각이 다릅니다."},{"p":"として","ko":"~로서","use":"역할·자격·입장을 나타낼 때","ex":"代表として参加します。","tr":"대표로서 참가합니다."},{"p":"にとって","ko":"~에게 있어서","use":"판단·평가의 입장을 나타낼 때","ex":"私にとって大切です。","tr":"저에게 중요합니다."},{"p":"でも","ko":"~라도/~나","use":"가볍게 예시를 제안할 때","ex":"コーヒーでも飲みませんか。","tr":"커피라도 마시지 않을래요?"},{"p":"なら","ko":"~라면","use":"상대가 꺼낸 화제를 조건으로 이어갈 때","ex":"京都なら秋がおすすめです。","tr":"교토라면 가을을 추천합니다."},{"p":"って","ko":"~라고/~는 말이야 · 회화체","use":"인용이나 화제를 일상 회화에서 가볍게 표시할 때","ex":"田中さんは明日来るって。","tr":"다나카 씨는 내일 온대."}];
