let state=loadState();
let lesson=null;
let speechRec=null;

function loadState(){
  try{
    let raw=localStorage.getItem(stateKey());
    if(!raw&&storageOwner()==='guest') raw=localStorage.getItem(LEGACY_KEY);
    let parsed=raw?JSON.parse(raw):{};
    let x=Object.assign({},defaultState,parsed);x.cards=x.cards||{};x.roles=x.roles||{};x.history=Array.isArray(x.history)?x.history:[];x.attendance=Array.isArray(x.attendance)?x.attendance:[];x.activity=Array.isArray(x.activity)?x.activity:[];x.lifeDrills=x.lifeDrills||{};x.jlptDrills=x.jlptDrills||{};x.jlptSession=x.jlptSession||null;return x;
  }catch(e){
    try{let b=JSON.parse(localStorage.getItem(backupKey())||'{}');let x=Object.assign({},defaultState,b);x.cards=x.cards||{};x.roles=x.roles||{};x.history=Array.isArray(x.history)?x.history:[];x.attendance=Array.isArray(x.attendance)?x.attendance:[];x.activity=Array.isArray(x.activity)?x.activity:[];return x}catch(_){return {...defaultState,cards:{},roles:{},history:[]}}
  }
}
function saveState(){
  state._updatedAt=Date.now();
  try{localStorage.setItem(stateKey(),JSON.stringify(state))}catch(e){}
  saveStateIDB(state);
  if(!window.__DACOCloudApplying) window.DACOCloud?.scheduleSync?.(state);
}
function openStateDB(){return new Promise((resolve,reject)=>{try{let req=indexedDB.open('daco_jp_coach_db',1);req.onupgradeneeded=()=>{let db=req.result;if(!db.objectStoreNames.contains('kv'))db.createObjectStore('kv')};req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error)}catch(e){reject(e)}})}
async function saveStateIDB(data){try{let db=await openStateDB();let tx=db.transaction('kv','readwrite');tx.objectStore('kv').put(JSON.parse(JSON.stringify(data)),idbKey());tx.oncomplete=()=>db.close()}catch(e){}}
async function hydrateFromIDB(){try{let db=await openStateDB();let data=await new Promise((resolve,reject)=>{let tx=db.transaction('kv','readonly');let req=tx.objectStore('kv').get(idbKey());req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error)});db.close();if(data&&Number(data._updatedAt||0)>Number(state._updatedAt||0)){state=Object.assign({},defaultState,data);try{localStorage.setItem(stateKey(),JSON.stringify(state))}catch(e){};updateHome();toast('이전 학습 기록을 복구했습니다.')}}catch(e){}}
async function requestPersistentStorage(){try{if(navigator.storage&&navigator.storage.persist)await navigator.storage.persist()}catch(e){}}

function saveBackupSnapshot(reason='auto'){
  try{const snap=JSON.parse(JSON.stringify(state));snap._backupReason=reason;snap._backupAt=Date.now();localStorage.setItem(backupKey(),JSON.stringify(snap));state._autoBackupAt=snap._backupAt;localStorage.setItem(stateKey(),JSON.stringify(state));return true}catch(e){return false}
}
function restoreAutoBackup(){
  try{const raw=localStorage.getItem(backupKey());if(!raw){toast('저장된 자동 백업이 없습니다.');return}const b=JSON.parse(raw);const when=b._backupAt?new Date(b._backupAt).toLocaleString():'이전 시점';if(!confirm(`${when} 자동 백업으로 학습 기록을 복원할까요?`))return;state=Object.assign({},defaultState,b);state.cards=state.cards||{};state.roles=state.roles||{};state.history=Array.isArray(state.history)?state.history:[];saveState();updateHome();closeSettings();toast('자동 백업에서 복원했습니다.')}catch(e){alert('자동 백업을 복원하지 못했습니다.')}
}

function todayKey(d=new Date()){return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0')}
function dayDiff(a,b){if(!a||!b)return 999;return Math.round((new Date(b+'T12:00:00')-new Date(a+'T12:00:00'))/86400000)}
function ensureGamificationState(s=state){
  if(!Array.isArray(s.attendance))s.attendance=[];if(!Array.isArray(s.activity))s.activity=[];
  const dates=new Set(s.attendance.filter(Boolean));(s.history||[]).forEach(h=>{if(h?.date)dates.add(h.date)});s.attendance=[...dates].sort().slice(-730);return s
}
function attendanceDates(s=state){ensureGamificationState(s);return [...new Set(s.attendance||[])].sort()}
function attendanceStreak(s=state){let ds=attendanceDates(s);if(!ds.length)return 0;let cur=ds[ds.length-1],n=1;for(let i=ds.length-2;i>=0;i--){if(dayDiff(ds[i],cur)===1){n++;cur=ds[i]}else break}return n}
function hasStudiedToday(s=state){let tk=todayKey();return s.lastStudy===tk||(s.history||[]).some(h=>h?.date===tk)||(s.activity||[]).some(a=>a?.date===tk&&['lesson','verb','ending','life','jlpt'].includes(a.type))}
function scoreSummary(s=state){
  ensureGamificationState(s);let hist=Array.isArray(s.history)?s.history:[],lessonPts=0,firstC=0,firstA=0;
  hist.forEach(h=>{let fc=Number(h?.firstCorrect||0),fa=Number(h?.firstAttempts||0),m=Number(h?.mastery||0);firstC+=fc;firstA+=fa;lessonPts+=30+fc*2+(m>=90?10:0)});
  let drills=Number(s.drills?.verb?.sessions||0)+Number(s.drills?.ending?.sessions||0),drillPts=drills*15;
  let lifeSessions=Object.values(s.lifeDrills||{}).reduce((a,x)=>a+Number(x?.sessions||0),0),lifePts=lifeSessions*12;
  let jlptSessions=Object.values(s.jlptDrills||{}).reduce((a,x)=>a+Number(x?.sessions||0),0),jlptPts=jlptSessions*12;
  let learned=Object.values(s.cards||{}).filter(v=>v&&v.seen).length,att=attendanceDates(s).length,score=lessonPts+drillPts+lifePts+jlptPts+learned+att*5;
  return {score,lessonPoints:lessonPts,drillPoints:drillPts,lifePoints:lifePts,jlptPoints:jlptPts,learnedPoints:learned,attendancePoints:att*5,totalSessions:Number(s.totalSessions||0),drillSessions:drills,lifeSessions,jlptSessions,learned,attendanceDays:att,attendanceStreak:attendanceStreak(s),streak:Number(s.streak||0),firstAccuracy:firstA?Math.round(firstC/firstA*100):0,lastStudy:s.lastStudy||''}
}
function markAttendance(reason='manual',silent=false,persist=true){ensureGamificationState(state);let tk=todayKey(),added=!state.attendance.includes(tk);if(added)state.attendance.push(tk);state.attendance=[...new Set(state.attendance)].sort().slice(-730);if(added){state.activity.push({date:tk,at:Date.now(),type:'attendance',reason});state.activity=state.activity.slice(-730);if(persist)saveState();if(!silent)toast('✅ 오늘 출석 완료! +5점')}else if(!silent)toast('오늘은 이미 출석했습니다.');if(added&&persist)updateHome();return added}
function touchStudyDay(type){let tk=todayKey(),diff=dayDiff(state.lastStudy,tk);if(state.lastStudy!==tk){state.streak=diff===1?(state.streak||0)+1:1;state.lastStudy=tk}markAttendance(type,true,false);ensureGamificationState(state);state.activity.push({date:tk,at:Date.now(),type});state.activity=state.activity.slice(-730)}
function manualAttendance(){markAttendance('manual',false,true);renderAttendanceModal();window.DACOCloud?.scheduleSync?.()}
function recentActivityCounts(days=7){let out=[],today=new Date();for(let i=days-1;i>=0;i--){let d=new Date(today);d.setDate(today.getDate()-i);let k=todayKey(d),count=(state.history||[]).filter(h=>h?.date===k).length+(state.activity||[]).filter(a=>a?.date===k&&['verb','ending','life','jlpt'].includes(a.type)).length;out.push({date:k,label:`${d.getMonth()+1}/${d.getDate()}`,count,att:attendanceDates(state).includes(k)})}return out}
function attendanceCalendarHtml(){let rows=[],today=new Date(),ds=new Set(attendanceDates(state));for(let i=27;i>=0;i--){let d=new Date(today);d.setDate(today.getDate()-i);let k=todayKey(d),on=ds.has(k),isToday=k===todayKey();rows.push(`<div class="attDay ${on?'on':''} ${isToday?'today':''}"><b>${d.getDate()}</b><span>${on?'✓':''}</span></div>`)}return `<div class="attCalendar">${rows.join('')}</div>`}
function renderAttendanceModal(){let box=document.getElementById('attendanceContent');if(!box)return;let m=scoreSummary(state),done=attendanceDates(state).includes(todayKey()),studied=hasStudiedToday(state);box.innerHTML=`<div class="attendanceHero ${done?'done':''}"><div class="attendanceIcon">${done?'✅':'📅'}</div><h2>${done?'오늘 출석 완료':'오늘 출석하기'}</h2><p>${studied?'오늘 학습을 완료했습니다.':'아직 오늘 학습 기록이 없습니다.'}</p>${done?'':`<button class="bigbtn blue" onclick="manualAttendance()">오늘 출석 체크 +5점</button>`}</div><div class="miniStats"><div><b>${m.attendanceDays}</b><span>누적 출석</span></div><div><b>${m.attendanceStreak}</b><span>출석 연속</span></div><div><b>${m.score.toLocaleString()}</b><span>현재 점수</span></div></div>${attendanceCalendarHtml()}<div class="reminderBox"><b>🔔 오후 7시 미학습 알림</b><p>앱을 닫아도 알림을 받으려면 Web Push 권한을 허용하세요.</p><button id="reminderToggleBtn" class="bigbtn light" onclick="DACOCloud.toggleReminder()">알림 상태 확인 중...</button><div id="reminderStatus" class="footerNote"></div></div>`;window.DACOCloud?.updateReminderUI?.()}
function openAttendance(){renderAttendanceModal();document.getElementById('attendanceModal').classList.add('on')}
function openMyPage(){renderMyPage();document.getElementById('myPageModal').classList.add('on');setTimeout(()=>window.DACOCloud?.fillMyRank?.(),0)}
function renderMyPage(){let box=document.getElementById('myPageContent');if(!box)return;let m=scoreSummary(state),days=recentActivityCounts(7),max=Math.max(1,...days.map(x=>x.count)),profile=window.DACOCloud?.profile,who=profile?.display_name||profile?.username||'학습자';box.innerHTML=`<div class="myHero"><div><small>ANTHONY 日本語 COACH</small><h2>${escapeHtml(who)}님의 학습 기록</h2><div class="myScore">${m.score.toLocaleString()} <span>점</span></div></div><div id="myPageRank" class="rankBadge">랭킹 확인 중...</div></div><div class="myStats"><div><b>${m.totalSessions}</b><span>10분 수업</span></div><div><b>${m.drillSessions}</b><span>활용 훈련</span></div><div><b>${m.lifeSessions}</b><span>생활 훈련</span></div><div><b>${m.jlptSessions||0}</b><span>JLPT 단어</span></div><div><b>${m.learned}</b><span>학습 카드</span></div><div><b>${m.firstAccuracy}%</b><span>첫 시도 정확도</span></div><div><b>${m.streak}</b><span>학습 연속일</span></div><div><b>${m.attendanceDays}</b><span>출석일</span></div></div><div class="panel" style="margin:14px 0 0"><h3>최근 7일 학습량</h3><div class="weekChart">${days.map(x=>`<div class="barCol"><div class="barNum">${x.count||''}</div><div class="bar" style="height:${Math.max(5,Math.round(x.count/max*82))}px"></div><span>${x.label}</span></div>`).join('')}</div></div><div class="panel" style="margin:14px 0 0"><h3>출석 현황</h3>${attendanceCalendarHtml()}</div><div class="scoreGuide"><b>점수 산정</b><span>수업 완료 30점 · 첫 시도 정답 2점 · 숙달 90%+ 10점 · 활용훈련 15점 · 생활훈련 12점 · JLPT 단어 12점 · 출석 5점 · 학습카드 1점</span></div>`}
function ensureReviewPrefs(){state.reviewPrefs=Object.assign({firstDelay:'immediate',customDays:1,autoGrow:true},state.reviewPrefs||{});state.reviewPlan=state.reviewPlan||{};return state.reviewPrefs}
function reviewInitialDays(){let p=ensureReviewPrefs(),v=p.firstDelay;if(v==='3')return 3;if(v==='7')return 7;if(v==='custom')return Math.max(0.01,Number(p.customDays||1));return 10/(60*24)}
function reviewInitialLabel(){let p=ensureReviewPrefs();if(p.firstDelay==='3')return '3일';if(p.firstDelay==='7')return '7일';if(p.firstDelay==='custom')return `${Math.max(0.01,Number(p.customDays||1))}일`;return '즉시(10분)'}
function reviewDelayMs(days){return Math.max(60*1000,Number(days||0)*86400000)}
function nextGrowingInterval(prev,reps){let p=ensureReviewPrefs(),base=reviewInitialDays();if(!p.autoGrow)return base;if(reps<=1)return base;if(base<1){if(reps===2)return 3;if(reps===3)return 7}if(reps===2)return Math.max(7,Math.round(base*2));if(reps===3)return Math.max(14,Math.round((prev||base)*2));return Math.min(365,Math.max((prev||base)+1,Math.round((prev||base)*2.05)))}
function reviewKeyForCard(c){return c?`card:${c.id}`:''}
function genericReviewState(key){state.reviewPlan=state.reviewPlan||{};return state.reviewPlan[key]||{reps:0,interval:0,due:0,last:0}}
function scheduleGenericReview(key,days=null,success=true){if(!key)return;let r=genericReviewState(key),now=Date.now();if(days==null){r.reps=(r.reps||0)+(success?1:0);let d=nextGrowingInterval(r.interval,r.reps||1);r.interval=d;r.due=now+reviewDelayMs(d)}else{let d=Math.max(0.001,Number(days));r.interval=d;r.due=now+reviewDelayMs(d);if(success)r.reps=Math.max(1,r.reps||0)}r.last=now;state.reviewPlan[key]=r;saveState()}
function setReviewPreset(v){let p=ensureReviewPrefs();p.firstDelay=v;saveState();syncReviewSettingsUI();toast(`첫 복습 기본값: ${reviewInitialLabel()}`)}
