function setCardReviewDays(cardId,days,label=''){let c=DB.cards.find(x=>x.id===cardId);if(!c)return;let p=cardState(cardId),now=Date.now(),d=Math.max(0.001,Number(days));p.interval=d;p.due=now+reviewDelayMs(d);p.last=now;state.cards[cardId]=p;saveState();toast(`복습 예약: ${label||((d<1)?'오늘':' '+d+'일 후')}`)}
