function shuffle(a){a=[...a];for(let i=a.length-1;i>0;i--){let j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]]}return a}
function cardAllowedForMode(c,mode=state.mode){
  if(!c||!c.jp||!c.ko||['—','-','–','―'].includes(String(c.jp).trim()))return false;
  if(mode==='beginner'){
    if(c.kind==='grammar')return c.level==='N5'||c.level==='N4';
    if(c.kind==='verb')return c.level==='기초';
    if(c.kind==='word')return ['기초','N5','N4'].includes(c.level);
    return ['adjective','katakana','particle','counter'].includes(c.kind);
  }
  if(mode==='business'){
    if(c.kind==='conversation')return BUSINESS_CONVERSATION_RE.test(c.category||'');
    if(['business','keigo'].includes(c.kind))return true;
    if(c.kind==='verb')return c.level==='N3·비즈니스';
    if(c.kind==='word')return c.level==='N3'&&/업무|메일|전화|제조|영업|회사|회의|출장|거래|일정|상태/.test(c.category||'');
    if(c.kind==='grammar')return /부탁|허가|의무|희망|계획|상태|준비|시간|순서|화제|전달|연결|경어/.test(c.category||'');
    return false;
  }
  if(mode==='n3'){
    if(c.kind==='grammar'||c.kind==='word')return c.level==='N3';
    if(c.kind==='verb')return c.level==='N3·비즈니스';
    return c.kind==='particle';
  }
  return true;
}
function startOfToday(){let d=new Date();d.setHours(0,0,0,0);return d.getTime()}
function weightedPool(mode=state.mode){
  const now=Date.now(),today=startOfToday();let base=DB.cards.filter(c=>cardAllowedForMode(c,mode));let primary=[],fallback=[];
  for(const c of base){let p=cardState(c.id),due=!!(p.seen&&p.due<=now),fresh=!p.seen,studiedToday=!!(p.last&&p.last>=today);if(studiedToday)continue;
    let weakness=(p.lapses||0)*4+((p.reps||0)===0?2:0),modeBoost=1;
    if(mode==='business'&&['business','conversation','keigo'].includes(c.kind))modeBoost=5;if(mode==='n3'&&c.level==='N3')modeBoost=5;if(mode==='beginner'&&(c.level==='기초'||c.level==='N5'||c.level==='N4'))modeBoost=3;
    let row={c,w:(due?14:0)+(fresh?7:0)+weakness+(c.priority||1)*modeBoost+Math.random()*2};(due||fresh?primary:fallback).push(row);
  }
  const sort=x=>x.sort((a,b)=>b.w-a.w).map(v=>v.c);return [...sort(primary),...sort(fallback)];
}
function pickUnique(pool,n,used=new Set()){const out=[];for(const c of pool){if(!used.has(c.id)){out.push(c);used.add(c.id);if(out.length>=n)break}}return out}
function newUid(){return 'i'+Date.now().toString(36)+Math.random().toString(36).slice(2,8)}
function decorateItem(it,extra={}){return Object.assign({},it,{uid:it.uid||newUid(),status:it.status||'pending',result:it.result||'',attempts:Number(it.attempts||0),hadWrong:!!it.hadWrong,isReview:!!it.isReview,reviewReason:it.reviewReason||'',roleIdx:Number(it.roleIdx||0),roleFailures:Number(it.roleFailures||0),roleSkipped:Number(it.roleSkipped||0),firstAttemptRecorded:!!it.firstAttemptRecorded,firstAttemptCorrect:!!it.firstAttemptCorrect},extra)}
function buildLesson(type){
  const quick=type==='quick',pool=weightedPool(state.mode),used=new Set();
  // 말하기를 건너뛴 카드는 다음 수업의 말하기 슬롯에서 우선 다시 만납니다.
  const speechPool=pool.filter(c=>['business','conversation','word','verb','grammar','keigo','katakana'].includes(c.kind)).sort((a,b)=>Number(!!state.cards?.[b.id]?.speechPending)-Number(!!state.cards?.[a.id]?.speechPending));
  const speaking=pickUnique(speechPool,quick?1:3,used).map(c=>({type:'speaking',card:c}));
  const recall=pickUnique(pool,quick?3:7,used).map(c=>({type:'recall',card:c}));
  const quiz=pickUnique(pool.filter(c=>c.kind!=='counter'),quick?2:4,used).map(c=>({type:'quiz',card:c}));
  const listening=pickUnique(pool.filter(c=>['business','conversation','word','verb','grammar','katakana'].includes(c.kind)),quick?1:3,used).map(c=>({type:'listening',card:c}));
  let items=[...recall,...quiz,...listening,...speaking];
  if(!quick){let roles=rolePool(state.mode);if(roles.length)items.push({type:'roleplay',role:roles[0]});else items.push(...pickUnique(pool,1,used).map(c=>({type:'quiz',card:c})))}
  return items.map(x=>decorateItem(x));
}
function rolePool(mode=state.mode){
  if(mode==='n3')return [];let r=DB.roleplays;
  if(mode==='beginner')r=r.filter(x=>/인사 표현|일상 대화|날씨|취미|자기소개|기본 대응|의사소통/.test((x.category||'')+' '+(x.situation||''))&&!/업무|회사|회의|출장|거래|메일|전화|접대|내방/.test((x.category||'')+' '+(x.situation||'')));
  if(mode==='business')r=r.filter(x=>/업무|회사|회의|출장|거래|메일|전화|접대|내방|이동|입국|호텔|식당|추가 출장/.test((x.category||'')+' '+(x.situation||'')));
  const today=startOfToday();let freshToday=r.filter(x=>!state.roles?.[x.id]?.last||state.roles[x.id].last<today);let src=freshToday.length?freshToday:r;
  return src.sort((a,b)=>reviewPriority(`role:${b.id}`)-reviewPriority(`role:${a.id}`));
}
function itemIdentity(it){return it?.type==='roleplay'?`role:${it.role?.id||''}`:`card:${it?.card?.id||''}`}
function recordFirstAttempt(it,ok){if(!lesson||!it||it.isReview||it.firstAttemptRecorded)return;it.firstAttemptRecorded=true;it.firstAttemptCorrect=!!ok;lesson.firstAttempts=(lesson.firstAttempts||0)+1;if(ok)lesson.firstCorrect=(lesson.firstCorrect||0)+1}
function markWeak(it){if(!lesson||!it)return;lesson.weakSet=lesson.weakSet||new Set();lesson.masterySet=lesson.masterySet||new Set();const id=itemIdentity(it);lesson.weakSet.add(id);lesson.masterySet.delete(id);lesson.weak=lesson.weakSet.size}
function markMastered(it){if(!lesson||!it)return;lesson.masterySet=lesson.masterySet||new Set();lesson.masterySet.add(itemIdentity(it))}
function isJapaneseReading(s){s=String(s||'').trim();return !!s&&!/[가-힣]/.test(s)&&/[ぁ-んァ-ヶー]/.test(s)}
function plainJP(t){
  let raw=String(t||'').trim();
  raw=raw.replace(/[\r\n]+\s*[（(][ぁ-んァ-ヶー\s。、！？!?・ーA-Za-z0-9]+[）)]\s*$/s,'');
  raw=raw.replace(/([一-龯々〆ヵヶ]+)[(（][ぁ-んァ-ヶー]+[)）]/g,'$1');
  raw=raw.replace(/[（(][^）)]*[가-힣][^）)]*[）)]/g,'');
  return cleanJP(raw).replace(/[（(]([^）)]+)[）)]/g,'$1')
}
function recognitionSimilarity(tx,display,audio){
  let a=normalizeJP(tx),b=normalizeJP(plainJP(display)),c=normalizeJP(speechJP(audio||display));
  return Math.max(similarity(a,b),similarity(a,c))
}
function cardExplicitReading(c){
  if(!c)return '';
  if(c.kind==='keigo'&&KEIGO_READING_MAP[c.jp])return KEIGO_READING_MAP[c.jp];
  if(c.kind==='grammar'&&GRAMMAR_READING_MAP[c.jp])return GRAMMAR_READING_MAP[c.jp];
  if(c.kind!=='katakana'&&isJapaneseReading(c.reading))return c.reading;
  return ''
}
function primaryVariantText(t){let s=cleanJP(t);if(!s.includes('/'))return s;return cleanJP(s.split(/\s*\/\s*/)[0])}
function wordAudioTarget(c){
  if(!c)return '';
  let explicit=cardExplicitReading(c);if(explicit)return primaryVariantText(explicit);
  return primaryVariantText(c.jp)
}
function exampleAudioTarget(c){
  if(!c?.extra?.example)return '';
  if(isJapaneseReading(c.extra.exampleReading))return cleanJP(c.extra.exampleReading);
  return cleanJP(c.extra.example)
}
function hasExampleAudio(c){let ex=exampleAudioTarget(c),word=wordAudioTarget(c);return !!(ex&&normalizeJP(ex)!==normalizeJP(word))}
function audioWordLabel(c){return c?.kind==='grammar'?'문법/표현 듣기':'단어/표현 듣기'}
function audioChoiceButtons(c,compact=false){let word=wordAudioTarget(c),ex=exampleAudioTarget(c),cls=compact?'audioPick':'bigbtn light';let a=`<button class="${cls}" onclick="speakText('${encodeURIComponent(word)}')">🔊 ${audioWordLabel(c)}</button>`;if(hasExampleAudio(c))a+=`<button class="${cls}" onclick="speakText('${encodeURIComponent(ex)}')">🔊 예문 듣기</button>`;return a}
function audioTarget(c){if(!c)return '';if(c.kind==='grammar'&&c.extra?.example)return exampleAudioTarget(c);return wordAudioTarget(c)}
function speakingTarget(c){return audioTarget(c)}
function speakingPrompt(c){if(c?.kind==='grammar'&&c.extra?.translation)return c.extra.translation;return c?.ko||''}
function clearSpeechPending(c){if(!c)return;let p=cardState(c.id);if(p.speechPending){p.speechPending=false;state.cards[c.id]=p}}
function speakingChoiceText(c){if(!c)return '';return c.kind==='grammar'&&c.extra?.example?cleanJP(c.extra.example):primaryVariantText(c.jp)}
function speakingChoicePool(c){let mode=lesson?.mode||state.mode,correct=speakingChoiceText(c),cand=DB.cards.filter(x=>cardAllowedForMode(x,mode)&&x.id!==c.id&&x.ko&&speakingChoiceText(x));let same=cand.filter(x=>x.kind===c.kind),rest=cand.filter(x=>x.kind!==c.kind),all=[...shuffle(same),...shuffle(rest)],out=[],seen=new Set([normalizeJP(correct)]);for(const x of all){let t=speakingChoiceText(x),k=normalizeJP(t);if(!t||seen.has(k))continue;seen.add(k);out.push(t);if(out.length>=3)break}return shuffle([correct,...out])}
function roleChoicePool(turn,role){let correct=primaryVariantText(turn?.jp||''),near=[],far=[];for(const r of DB.roleplays){for(const t of (r.turns||[])){if(!/🙋|나/.test(t.speaker||''))continue;let text=primaryVariantText(t.jp||'');if(!text||normalizeJP(text)===normalizeJP(correct))continue;((r.category===role?.category||r.situation===role?.situation)?near:far).push(text)}}let out=[],seen=new Set([normalizeJP(correct)]);for(const t of [...shuffle(near),...shuffle(far)]){let k=normalizeJP(t);if(seen.has(k))continue;seen.add(k);out.push(t);if(out.length>=3)break}return shuffle([correct,...out])}
function listeningChoiceLabel(c){return c?.ko||''}
function promptKey(c,type='quiz'){let t=type==='listening'?wordAudioTarget(c):cleanJP(c.jp);return normalizeJP(speechJP(t))}
function reviewUniqueCount(){if(!lesson)return 0;return new Set(lesson.items.filter(x=>x.isReview).map(itemIdentity)).size}

function serializeLessonItem(it){let x={type:it.type,uid:it.uid,status:it.status||'pending',result:it.result||'',attempts:it.attempts||0,hadWrong:!!it.hadWrong,isReview:!!it.isReview,reviewReason:it.reviewReason||'',roleIdx:it.roleIdx||0,roleFailures:it.roleFailures||0,roleSkipped:it.roleSkipped||0,firstAttemptRecorded:!!it.firstAttemptRecorded,firstAttemptCorrect:!!it.firstAttemptCorrect};if(it.type==='roleplay')x.roleId=it.role?.id;else x.cardId=it.card?.id;return x}
function serializeLesson(){if(!lesson)return null;return {version:5.0,mode:lesson.mode||state.mode,sessionType:lesson.sessionType||'daily',idx:lesson.idx||0,answers:lesson.answers||0,correct:lesson.correct||0,weak:lesson.weakSet?.size||0,firstAttempts:lesson.firstAttempts||0,firstCorrect:lesson.firstCorrect||0,seen:[...(lesson.seen||new Set())],weakSet:[...(lesson.weakSet||new Set())],masterySet:[...(lesson.masterySet||new Set())],reviewCounts:lesson.reviewCounts||{},srs:lesson.srs||{},baseCount:lesson.baseCount||0,items:(lesson.items||[]).map(serializeLessonItem).filter(x=>x.cardId||x.roleId),savedAt:Date.now()}}
