function renderNav(){if(!lesson)return;let p=document.getElementById('prevNav'),n=document.getElementById('nextNav'),notice=document.getElementById('reviewNotice');if(p)p.disabled=lesson.idx<=0;if(n)n.textContent=lesson.idx>=lesson.items.length-1?'완료 →':'다음 →';let q=pendingReviewCount(),total=lesson.items.filter(x=>x.isReview).length;if(notice)notice.textContent=q?`🔁 추가복습 ${q}개 남음 · 지금까지 ${total}개 생성`:(total?`✓ 추가복습 ${total}개 완료`:' ')}
