  const baseDone=lesson.items.filter(x=>!x.isReview&&x.status==='done').length,reviewTotal=lesson.items.filter(x=>x.isReview).length,reviewDone=lesson.items.filter(x=>x.isReview&&x.status==='done').length;
  document.getElementById('lessonCount').textContent=`기본 ${baseDone}/${lesson.baseCount}${reviewTotal?` +복습 ${reviewDone}/${reviewTotal}`:''}`;document.getElementById('progressBar').style.width=(baseDone/Math.max(1,lesson.baseCount)*100)+'%';renderNav();
  const it=current();if(it.status==='done'){renderCompletedItem(it);return}if(it.type==='recall')renderRecall(it.card);else if(it.type==='quiz')renderQuiz(it.card);else if(it.type==='listening')renderListening(it.card);else if(it.type==='speaking')renderSpeaking(it.card);else renderRoleplay(it.role);
