function nextNavItem(){if(!lesson)return;let it=current();if(it&&it.status!=='done'){recordFirstAttempt(it,false);markWeak(it);queueReview(it,'건너뜀',3,true);if(it.card)schedule(it.card,'again');it.status='done';it.result='skipped';toast('건너뛴 항목은 뒤에서 다시 나옵니다.')}lesson.idx++;saveLessonState();renderItem()}
