function queueReview(it,reason='재복습',delay=4,manual=false){if(!lesson||!it)return false;let key=itemKey(it),future=lesson.items.slice(lesson.idx+1).find(x=>x.status!=='done'&&x.isReview&&itemKey(x)===key);if(future)return false;let cnt=Number(lesson.reviewCounts[key]||0);if(!manual&&cnt>=3)return false;let clone=cloneReviewItem(it,reason),pos=Math.min(lesson.items.length,lesson.idx+Math.max(2,delay));lesson.items.splice(pos,0,clone);lesson.reviewCounts[key]=cnt+1;saveLessonState();return true}
