function label(c){return `${KIND_LABEL[c.kind]||c.kind}${c.level?' · '+c.level:''}${c.category?' · '+c.category:''}`}
function cleanJP(t){return String(t||'').replace(/\n/g,' ').replace(/\s+/g,' ').trim()}
function speechJP(t){
  let raw=String(t||'').trim();if(!raw)return '';
  // A full reading written on the last line in parentheses is authoritative.
  // Example: 日本語で…\n(にほんご で…) -> only the reading is spoken once.
  let full=raw.match(/^(.*?)[\r\n]+\s*[（(]([ぁ-んァ-ヶー\s。、！？!?・ーA-Za-z0-9]+)[）)]\s*$/s);
  if(full&&/[一-龯々]/.test(full[1])&&!/[一-龯々]/.test(full[2])&&full[2].replace(/\s/g,'').length>=4)raw=full[2];
  let s=cleanJP(raw);
  if(TTS_READING_OVERRIDES[s])return TTS_READING_OVERRIDES[s];
  // Inline furigana is used as the actual TTS text instead of discarding it.
  // 気(き)に入(い)る -> きにいる / 日本料理(にほんりょうり) -> にほんりょうり
  s=s.replace(/([一-龯々〆ヵヶ]+)[(（]([ぁ-んァ-ヶー]+)[)）]/g,'$2');
  // Korean explanatory parentheses are never spoken.
  s=s.replace(/[（(][^）)]*[가-힣][^）)]*[）)]/g,'');
  // Optional kana such as 〜(さ)せる or アポ(イント) is joined naturally.
  s=s.replace(/[（(]([^）)]+)[）)]/g,'$1');
  return s.replace(/\s*\/\s*/g,'、').replace(/\s+/g,' ').trim()
}
function cleanReading(t){return String(t||'').replace(/\n/g,' ').replace(/\s+/g,' ').trim()}
