  const baseIds=new Set(lesson.items.filter(x=>!x.isReview).map(itemIdentity)),mastered=[...(lesson.masterySet||new Set())].filter(x=>baseIds.has(x)).length,masteryPct=baseIds.size?Math.round(mastered/baseIds.size*100):0,firstPct=lesson.firstAttempts?Math.round(lesson.firstCorrect/lesson.firstAttempts*100):0,reviews=reviewUniqueCount(),weak=(lesson.weakSet||new Set()).size;
  state.history=Array.isArray(state.history)?state.history:[];state.history.push({date:tk,at:Date.now(),mode:lesson.mode||state.mode,items:lesson.seen.size,firstCorrect:lesson.firstCorrect,firstAttempts:lesson.firstAttempts,firstAccuracy:firstPct,mastery:masteryPct,weak,reviews});state.history=state.history.slice(-180);state.activeSession=null;saveState();saveBackupSnapshot('수업 완료');
